  z-index: 6;
  pointer-events: none;
}
.route-dock__card {
  position: relative;
  pointer-events: auto;
  box-sizing: border-box;
  padding: 6px 8px 8px 12px;
  border-radius: 12px;
  background: #fff;
  color: #121417;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.28);
}
.route-dock-anchor:not(.route-dock-anchor--open) {
  width: auto;
}
.route-dock-anchor:not(.route-dock-anchor--open) .route-dock__grid {
  display: none;
}
.route-dock-anchor:not(.route-dock-anchor--open) .route-dock__card {
  width: 28px;
  height: 28px;
  min-width: 28px;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
/* 맨 위 줄: 접기 LED(왼쪽) · 센서 알약. */
