  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-height: 30px;
  padding-left: 32px;
  margin-bottom: 2px;
}
.route-dock__fold {
  position: absolute;
  top: 4px;
  left: 4px;
  z-index: 2;
}
.route-dock-anchor--open .route-dock__card--head { padding-top: 3px; }
.route-dock__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
}
