  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}
.route-dock__badge--start { background: #16a34a; }
.route-dock__badge--end { background: #dc2626; }
.route-dock__badge--waypoint {
  background: linear-gradient(145deg, rgba(234, 179, 8, 0.95), rgba(180, 83, 9, 0.92));
  color: #fefce8;
}
.route-dock__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.route-dock__remove {
  flex: 0 0 22px;
