.route-dock__head .hud-cadence--dock,
.route-dock__head .hud-cadence--dock:hover {
  position: static;
  transform: none;
  width: auto;
  height: 30px;
  min-height: 30px;
  gap: 6px;
  padding: 0 13px 0 11px;
  border: 1px solid #c9d6ee;
  border-radius: 999px;
  background: #fff;
  color: #2a2e37;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  backdrop-filter: none;
}
.route-dock__head .hud-cadence--dock.hud-cadence--open { border-color: #2457d6; background: #fff; }
@media (hover: hover) {
  .route-dock__head .hud-cadence--dock:hover { border-color: #2457d6; }
}
.route-dock__head .hud-cadence--dock .hud-cadence__text { display: inline; min-width: 0; }
.route-dock__head .hud-cadence--dock .hud-cadence__led {
  width: 7px;
  height: 7px;
  box-sizing: border-box;
}
.route-dock__head .hud-cadence--dock .hud-cadence__led--white {
  background: transparent;
  border: 1.5px solid currentColor;
  box-shadow: none;
}
.route-dock__head .hud-cadence--dock .hud-cadence__led--green {
  background: #1e9a55;
  box-shadow: none;
}
/* 다음 할 일 안내(2026-09-18 Chief 깜빡임 유지) — 강조색은 accent 하나. */
.route-dock__head .hud-cadence--dock.hud-cadence--attention {
  animation: route-dock-sensor-attention 1.1s ease-in-out infinite;
}
@keyframes route-dock-sensor-attention {
  0%, 100% { border-color: #c9d6ee; background: #fff; color: #2a2e37; }
  50% { border-color: #2457d6; background: #eef3fc; color: #2457d6; }
}
@media (prefers-reduced-motion: reduce) {
  .route-dock__head .hud-cadence--dock.hud-cadence--attention {
    animation: none;
    border-color: #2457d6;
    color: #2457d6;
  }
}

